def anreden_anlegen(apps, schema_editor):
    Anrede = apps.get_model("stammdaten", "Anrede")
    for nummer, text in ANREDEN:
        Anrede.objects.get_or_create(nummer=nummer, defaults={"bezeichnung": text})


def anreden_zuordnen(apps, schema_editor):
    Anrede = apps.get_model("stammdaten", "Anrede")
    karte = {a.bezeichnung.casefold(): a for a in Anrede.objects.all()}

    def finden(text):
        text = (text or "").strip()
        if not text:
            return None
        if text.casefold() not in karte:  # z. B. „Dr.“ beim Ansprechpartner: als eigene Anrede übernehmen
            nummer = (Anrede.objects.aggregate(m=models.Max("nummer"))["m"] or 0) + 1
            karte[text.casefold()] = Anrede.objects.create(nummer=nummer, bezeichnung=text[:30])
        return karte[text.casefold()]

    for modell in ("Kunde", "Ansprechpartner"):
        M = apps.get_model("stammdaten", modell)
        for obj in M.objects.exclude(anrede_alt="").only("pk", "anrede_alt"):
            M.objects.filter(pk=obj.pk).update(anrede=finden(obj.anrede_alt))


def zahlungsbedingungen_uebernehmen(apps, schema_editor):
    Zahlungsbedingung = apps.get_model("stammdaten", "Zahlungsbedingung")
    for nummer, text, real, intern, stop in ZAHLUNGSBEDINGUNGEN:
        obj = Zahlungsbedingung.objects.filter(nummer=nummer).first() or Zahlungsbedingung(nummer=nummer)
        werte = {"tage_netto": real, "tage_mahnung": intern, "tage_lieferstop": stop}
        if not Zahlungsbedingung.objects.filter(bezeichnung=text).exclude(pk=obj.pk).exists():  # Text eindeutig halten
            werte["bezeichnung"] = text
        elif obj.pk is None:
            continue
        for feld, wert in werte.items():
            setattr(obj, feld, wert)
        obj.save()


